echo '== guard'; node $P/guard.mjs src src/cards/model.ts,src/cards/types.ts; node $P/guard.mjs tests tests/cards/model.test.ts 1 5
echo '== probe'; node_modules/.bin/vitest run --config $P/probe.config.mts --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== own'; node_modules/.bin/vitest run tests/cards/model.test.ts --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== full'; node_modules/.bin/vitest run --passWithNoTests --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== frozen'; git diff --quiet HEAD -- contour.yaml morph-map.json docs decks tests/fixtures || { echo "changed outside the targets: $(git diff --name-only HEAD -- contour.yaml morph-map.json docs decks tests/fixtures | tr "\n" " ")"; exit 1; }
X=$(git ls-files --others --exclude-standard | grep -vxF -e src/cards/model.ts -e src/cards/types.ts -e tests/cards/model.test.ts || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc

