  const got = readResponse("a.v1", 200, "<html>bad gateway</html>");
  expect(got.answer, "answer").toStrictEqual(failed("a.v1", "unreadable response: <html>bad gateway</html>"));
  expect(got.usage, "usage").toStrictEqual(zero("a.v1"));
